[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>StayQuest — Find deals for any season</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  :root {
    --navy: #003B95;
    --blue: #006CE4;
    --gold: #FFB700;
    --gold-dark: #E6A500;
    --white: #ffffff;
    --gray-50: #f8f9fa;
    --gray-100: #f1f3f5;
    --gray-200: #e9ecef;
    --gray-300: #dee2e6;
    --gray-500: #868e96;
    --gray-700: #495057;
    --gray-900: #212529;
    --green: #008234;
    --radius: 8px;
    --shadow: 0 2px 8px rgba(0,0,0,.12);
    --shadow-md: 0 4px 16px rgba(0,0,0,.14);
  }
  body { font-family: 'Inter', sans-serif; color: var(--gray-900); background: var(--white); }
  a { color: inherit; text-decoration: none; }
  img { display: block; max-width: 100%; }
  button { cursor: pointer; font-family: inherit; }

  /* NAV */
  .topbar { background: var(--navy); padding: 6px 0; }
  .topbar-inner { max-width: 1200px; margin: 0 auto; padding: 0 20px; display: flex; justify-content: flex-end; gap: 16px; }
  .topbar a { color: rgba(255,255,255,.85); font-size: 13px; }
  .topbar a:hover { color: #fff; }
  nav { background: var(--navy); border-bottom: 1px solid rgba(255,255,255,.15); position: sticky; top: 0; z-index: 100; }
  .nav-inner { max-width: 1200px; margin: 0 auto; padding: 0 20px; display: flex; align-items: center; gap: 8px; }
  .nav-logo { color: #fff; font-size: 22px; font-weight: 800; padding: 14px 0; margin-right: 20px; letter-spacing: -0.5px; }
  .nav-logo span { color: var(--gold); }
  .nav-tabs { display: flex; gap: 2px; }
  .nav-tab { display: flex; align-items: center; gap: 6px; color: rgba(255,255,255,.85); font-size: 14px; font-weight: 500; padding: 10px 14px; border-radius: 4px; border: 1px solid transparent; transition: all .15s; white-space: nowrap; }
  .nav-tab:hover { background: rgba(255,255,255,.1); color: #fff; }
  .nav-tab.active { background: rgba(255,255,255,.15); color: #fff; border-color: rgba(255,255,255,.3); }
  .nav-tab svg { width: 18px; height: 18px; }
  .nav-right { margin-left: auto; display: flex; gap: 8px; align-items: center; }
  .btn-outline-white { border: 1.5px solid rgba(255,255,255,.6); color: #fff; background: transparent; padding: 7px 16px; border-radius: 4px; font-size: 14px; font-weight: 500; transition: all .15s; }
  .btn-outline-white:hover { background: rgba(255,255,255,.1); }
  .btn-primary { background: var(--gold); color: var(--gray-900); padding: 7px 16px; border-radius: 4px; font-size: 14px; font-weight: 700; border: none; transition: background .15s; }
  .btn-primary:hover { background: var(--gold-dark); }

  /* HERO */
  .hero { background: linear-gradient(135deg, var(--navy) 0%, #0052CC 60%, #006CE4 100%); padding: 48px 20px 0; position: relative; overflow: hidden; }
  .hero::after { content: ''; position: absolute; bottom: 0; left: 0; right: 0; height: 60px; background: var(--white); clip-path: ellipse(55% 100% at 50% 100%); }
  .hero-inner { max-width: 860px; margin: 0 auto; }
  .hero h1 { color: #fff; font-size: clamp(28px, 4vw, 44px); font-weight: 800; line-height: 1.1; margin-bottom: 8px; }
  .hero p { color: rgba(255,255,255,.85); font-size: 18px; margin-bottom: 28px; }
  .search-box { background: var(--white); border-radius: 12px; padding: 20px; box-shadow: 0 4px 24px rgba(0,0,0,.25); margin-bottom: 60px; }
  .search-row { display: flex; gap: 8px; align-items: stretch; flex-wrap: wrap; }
  .search-field { flex: 1; min-width: 160px; display: flex; flex-direction: column; border: 1.5px solid var(--gray-300); border-radius: var(--radius); padding: 10px 14px; transition: border-color .15s; }
  .search-field:focus-within { border-color: var(--blue); }
  .search-field label { font-size: 11px; font-weight: 600; color: var(--gray-500); text-transform: uppercase; letter-spacing: .5px; margin-bottom: 3px; }
  .search-field input { border: none; outline: none; font-size: 14px; font-weight: 500; color: var(--gray-900); background: transparent; }
  .search-field input::placeholder { color: var(--gray-500); }
  .search-btn { background: var(--blue); color: #fff; border: none; border-radius: var(--radius); padding: 0 28px; font-size: 16px; font-weight: 700; white-space: nowrap; min-height: 52px; transition: background .15s; }
  .search-btn:hover { background: #0055bb; }
  .search-extras { margin-top: 12px; display: flex; align-items: center; gap: 6px; }
  .search-extras input[type=checkbox] { width: 16px; height: 16px; accent-color: var(--blue); }
  .search-extras label { font-size: 14px; color: var(--gray-700); cursor: pointer; }

  /* SECTION COMMON */
  .section { padding: 48px 20px; }
  .section-alt { background: var(--gray-50); }
  .container { max-width: 1200px; margin: 0 auto; }
  .section-header { margin-bottom: 28px; }
  .section-header h2 { font-size: clamp(20px, 2.5vw, 28px); font-weight: 800; color: var(--gray-900); margin-bottom: 6px; }
  .section-header p { font-size: 15px; color: var(--gray-500); }
  .section-header-row { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; margin-bottom: 28px; }
  .section-header-row h2 { font-size: clamp(20px, 2.5vw, 28px); font-weight: 800; }
  .link-btn { color: var(--blue); font-size: 14px; font-weight: 600; white-space: nowrap; }
  .link-btn:hover { text-decoration: underline; }

  /* TRUST BADGES */
  .trust-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 20px; }
  .trust-card { display: flex; align-items: flex-start; gap: 14px; padding: 20px; background: var(--white); border-radius: var(--radius); border: 1px solid var(--gray-200); }
  .trust-icon { width: 44px; height: 44px; background: #EBF3FF; border-radius: 50%; display: flex; align-items: center; justify-content: center; flex-shrink: 0; color: var(--blue); }
  .trust-icon svg { width: 22px; height: 22px; }
  .trust-card h4 { font-size: 14px; font-weight: 700; margin-bottom: 3px; color: var(--gray-900); }
  .trust-card p { font-size: 13px; color: var(--gray-500); line-height: 1.4; }

  /* OFFERS */
  .offers-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px; }
  .offer-card { border-radius: 12px; padding: 28px; display: flex; flex-direction: column; gap: 12px; }
  .offer-card.deal { background: linear-gradient(135deg, #003B95, #006CE4); color: #fff; }
  .offer-card.credit { background: linear-gradient(135deg, #1A1A2E, #16213E); color: #fff; }
  .offer-card h3 { font-size: 20px; font-weight: 800; line-height: 1.2; }
  .offer-card p { font-size: 14px; opacity: .85; line-height: 1.5; flex: 1; }
  .offer-cta { display: inline-block; background: var(--gold); color: var(--gray-900); font-weight: 700; font-size: 14px; padding: 10px 20px; border-radius: var(--radius); transition: background .15s; width: fit-content; }
  .offer-cta:hover { background: var(--gold-dark); }

  /* PROPERTY TYPES */
  .pill-grid { display: flex; flex-wrap: wrap; gap: 8px; }
  .pill { background: var(--white); border: 1.5px solid var(--gray-300); color: var(--gray-700); font-size: 13px; font-weight: 500; padding: 7px 14px; border-radius: 20px; transition: all .15s; cursor: pointer; }
  .pill:hover { border-color: var(--blue); color: var(--blue); background: #EBF3FF; }

  /* TABS */
  .tabs { display: flex; gap: 4px; flex-wrap: wrap; border-bottom: 2px solid var(--gray-200); margin-bottom: 24px; }
  .tab-btn { padding: 10px 16px; font-size: 14px; font-weight: 500; color: var(--gray-500); background: transparent; border: none; border-bottom: 2px solid transparent; margin-bottom: -2px; transition: all .15s; cursor: pointer; white-space: nowrap; }
  .tab-btn:hover { color: var(--blue); }
  .tab-btn.active { color: var(--blue); border-bottom-color: var(--blue); font-weight: 700; }
  .tab-panel { display: none; }
  .tab-panel.active { display: block; }

  /* TRIP PLANNER */
  .dest-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 12px; }
  .dest-card { border: 1.5px solid var(--gray-200); border-radius: var(--radius); padding: 14px 16px; transition: all .15s; cursor: pointer; }
  .dest-card:hover { border-color: var(--blue); box-shadow: var(--shadow); transform: translateY(-2px); }
  .dest-card h4 { font-size: 15px; font-weight: 700; margin-bottom: 3px; }
  .dest-card p { font-size: 12px; color: var(--gray-500); }

  /* UNIQUE PROPERTIES CAROUSEL */
  .carousel-wrap { position: relative; }
  .carousel { display: flex; gap: 16px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; padding-bottom: 4px; }
  .carousel::-webkit-scrollbar { display: none; }
  .carousel-arrow { position: absolute; top: 50%; transform: translateY(-50%); width: 40px; height: 40px; background: var(--white); border: 1.5px solid var(--gray-300); border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: var(--shadow); cursor: pointer; transition: all .15s; z-index: 2; }
  .carousel-arrow:hover { border-color: var(--blue); color: var(--blue); }
  .carousel-arrow.left { left: -20px; }
  .carousel-arrow.right { right: -20px; }
  .carousel-arrow svg { width: 18px; height: 18px; }
  .prop-card { flex: 0 0 220px; scroll-snap-align: start; border: 1.5px solid var(--gray-200); border-radius: 12px; overflow: hidden; transition: box-shadow .15s; }
  .prop-card:hover { box-shadow: var(--shadow-md); }
  .prop-img { width: 100%; height: 140px; background: linear-gradient(135deg, #b2c9f0, #d6e4ff); display: flex; align-items: center; justify-content: center; }
  .prop-img svg { width: 40px; height: 40px; color: rgba(0,60,150,.25); }
  .prop-body { padding: 12px 14px; }
  .prop-body h4 { font-size: 13px; font-weight: 700; margin-bottom: 3px; line-height: 1.3; }
  .prop-loc { font-size: 12px; color: var(--gray-500); margin-bottom: 6px; }
  .prop-rating { display: flex; align-items: center; gap: 6px; margin-bottom: 8px; }
  .rating-badge { background: var(--navy); color: #fff; font-size: 12px; font-weight: 700; padding: 2px 7px; border-radius: 4px; }
  .rating-label { font-size: 12px; color: var(--gray-700); }
  .reviews { font-size: 11px; color: var(--gray-500); }
  .prop-price { font-size: 16px; font-weight: 800; color: var(--gray-900); }
  .prop-price s { font-size: 13px; color: var(--gray-500); font-weight: 400; margin-right: 4px; }

  /* TRENDING DESTINATIONS */
  .trending-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 16px; }
  .trending-card { border-radius: 12px; overflow: hidden; position: relative; cursor: pointer; }
  .trending-img { height: 140px; background: linear-gradient(135deg, #4a90d9, #003B95); display: flex; align-items: center; justify-content: center; }
  .trending-img.p { background: linear-gradient(135deg, #c0392b, #8e44ad); }
  .trending-img.t { background: linear-gradient(135deg, #d35400, #e74c3c); }
  .trending-img.a { background: linear-gradient(135deg, #16a085, #27ae60); }
  .trending-img.r { background: linear-gradient(135deg, #8e44ad, #3498db); }
  .trending-img svg { width: 40px; height: 40px; color: rgba(255,255,255,.4); }
  .trending-overlay { position: absolute; bottom: 0; left: 0; right: 0; padding: 12px 14px; background: linear-gradient(to top, rgba(0,0,0,.7), transparent); color: #fff; }
  .trending-overlay h4 { font-size: 15px; font-weight: 700; }

  /* EXPLORE DESTINATIONS GRID */
  .city-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 12px; }
  .city-card { border-radius: 12px; overflow: hidden; cursor: pointer; }
  .city-img { height: 120px; display: flex; align-items: center; justify-content: center; position: relative; }
  .city-img.lv { background: linear-gradient(135deg, #f39c12, #d35400); }
  .city-img.or { background: linear-gradient(135deg, #27ae60, #2980b9); }
  .city-img.ny { background: linear-gradient(135deg, #2c3e50, #3498db); }
  .city-img.at { background: linear-gradient(135deg, #8e44ad, #3498db); }
  .city-img.la { background: linear-gradient(135deg, #f39c12, #e74c3c); }
  .city-img.ch { background: linear-gradient(135deg, #2980b9, #1abc9c); }
  .city-img.ho { background: linear-gradient(135deg, #d35400, #c0392b); }
  .city-img.sa { background: linear-gradient(135deg, #27ae60, #f39c12); }
  .city-img.mi { background: linear-gradient(135deg, #2980b9, #f39c12); }
  .city-img.sd { background: linear-gradient(135deg, #16a085, #2980b9); }
  .city-img svg { width: 36px; height: 36px; color: rgba(255,255,255,.35); }
  .city-info { padding: 10px 12px; background: var(--white); border: 1px solid var(--gray-200); border-top: none; border-radius: 0 0 12px 12px; }
  .city-info h4 { font-size: 14px; font-weight: 700; }
  .city-info p { font-size: 12px; color: var(--gray-500); }

  /* WEEKEND DEALS */
  .deals-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 16px; }
  .deal-card { border: 1.5px solid var(--gray-200); border-radius: 12px; overflow: hidden; transition: box-shadow .15s; }
  .deal-card:hover { box-shadow: var(--shadow-md); }
  .deal-img { height: 140px; background: linear-gradient(135deg, #667eea, #764ba2); display: flex; align-items: center; justify-content: center; }
  .deal-img.d1 { background: linear-gradient(135deg, #f093fb, #f5576c); }
  .deal-img.d2 { background: linear-gradient(135deg, #4facfe, #00f2fe); }
  .deal-img.d3 { background: linear-gradient(135deg, #43e97b, #38f9d7); }
  .deal-img.d4 { background: linear-gradient(135deg, #f6d365, #fda085); }
  .deal-img.d5 { background: linear-gradient(135deg, #a18cd1, #fbc2eb); }
  .deal-img svg { width: 36px; height: 36px; color: rgba(255,255,255,.4); }
  .deal-body { padding: 14px 16px; }
  .deal-body h4 { font-size: 14px; font-weight: 700; margin-bottom: 3px; }
  .deal-body .loc { font-size: 12px; color: var(--gray-500); margin-bottom: 8px; }
  .deal-rating { display: flex; align-items: center; gap: 6px; margin-bottom: 8px; }
  .deal-duration { font-size: 12px; color: var(--gray-500); }
  .deal-pricing { display: flex; align-items: center; gap: 8px; margin-top: 8px; }
  .deal-original { font-size: 13px; color: var(--gray-500); text-decoration: line-through; }
  .deal-sale { font-size: 18px; font-weight: 800; color: var(--green); }

  /* HOMES GUESTS LOVE */
  .homes-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 16px; }
  .home-card { border: 1.5px solid var(--gray-200); border-radius: 12px; overflow: hidden; transition: box-shadow .15s; cursor: pointer; }
  .home-card:hover { box-shadow: var(--shadow-md); }
  .home-img { height: 150px; display: flex; align-items: center; justify-content: center; }
  .home-img.h1 { background: linear-gradient(135deg, #c471ed, #12c2e9); }
  .home-img.h2 { background: linear-gradient(135deg, #f7971e, #ffd200); }
  .home-img.h3 { background: linear-gradient(135deg, #11998e, #38ef7d); }
  .home-img.h4 { background: linear-gradient(135deg, #ee0979, #ff6a00); }
  .home-img.h5 { background: linear-gradient(135deg, #2193b0, #6dd5ed); }
  .home-img.h6 { background: linear-gradient(135deg, #1565C0, #b92b27); }
  .home-img svg { width: 36px; height: 36px; color: rgba(255,255,255,.4); }
  .home-body { padding: 12px 14px; }
  .home-body h4 { font-size: 13px; font-weight: 700; margin-bottom: 3px; }
  .home-body .loc { font-size: 12px; color: var(--gray-500); margin-bottom: 6px; }
  .home-footer { display: flex; align-items: center; justify-content: space-between; margin-top: 8px; }
  .home-price { font-size: 16px; font-weight: 800; }

  /* LOYALTY CTA */
  .loyalty-section { background: linear-gradient(135deg, var(--navy) 0%, #006CE4 100%); padding: 56px 20px; }
  .loyalty-inner { max-width: 1200px; margin: 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 32px; flex-wrap: wrap; }
  .loyalty-text { color: #fff; }
  .loyalty-text h2 { font-size: 32px; font-weight: 800; margin-bottom: 6px; }
  .loyalty-text h3 { font-size: 20px; font-weight: 700; margin-bottom: 10px; opacity: .9; }
  .loyalty-text p { font-size: 15px; opacity: .8; max-width: 480px; }
  .loyalty-actions { display: flex; gap: 12px; flex-wrap: wrap; }
  .btn-white { background: #fff; color: var(--navy); font-weight: 700; padding: 12px 28px; border-radius: var(--radius); font-size: 15px; border: none; transition: background .15s; }
  .btn-white:hover { background: var(--gray-100); }
  .btn-outline { border: 2px solid rgba(255,255,255,.6); color: #fff; background: transparent; font-weight: 700; padding: 12px 28px; border-radius: var(--radius); font-size: 15px; transition: all .15s; }
  .btn-outline:hover { background: rgba(255,255,255,.1); }

  /* POPULAR LINKS */
  .links-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 8px 16px; }
  .links-grid a { font-size: 14px; color: var(--blue); padding: 4px 0; }
  .links-grid a:hover { text-decoration: underline; }

  /* FOOTER */
  footer { background: var(--gray-900); color: rgba(255,255,255,.7); padding: 48px 20px 24px; margin-top: 0; }
  .footer-inner { max-width: 1200px; margin: 0 auto; }
  .footer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 32px; margin-bottom: 40px; }
  .footer-col h4 { color: #fff; font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .8px; margin-bottom: 14px; }
  .footer-col a { display: block; font-size: 13px; color: rgba(255,255,255,.6); margin-bottom: 8px; transition: color .15s; }
  .footer-col a:hover { color: #fff; }
  .footer-bottom { border-top: 1px solid rgba(255,255,255,.1); padding-top: 20px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; }
  .footer-logo { font-size: 18px; font-weight: 800; color: #fff; }
  .footer-logo span { color: var(--gold); }
  .footer-tagline { font-size: 12px; color: rgba(255,255,255,.45); }

  /* RESPONSIVE */
  @media (max-width: 768px) {
    .nav-tabs { display: none; }
    .search-row { flex-direction: column; }
    .search-btn { width: 100%; }
    .carousel-arrow { display: none; }
    .loyalty-inner { flex-direction: column; }
  }
</style>
</head>
<body>

<!-- TOP BAR -->
<div class="topbar">
  <div class="topbar-inner">
    <a href="#">USD</a>
    <a href="#">EN</a>
