    <div class="nav-right">
      <button class="btn-outline-white">Register</button>
      <button class="btn-primary">Sign in</button>
    </div>
  </div>
</nav>

<!-- HERO -->
<section class="hero">
  <div class="hero-inner">
    <h1>Find deals for any season</h1>
    <p>From cozy bed &amp; breakfasts to luxury hotels</p>
