<script>
  // Generic tab switcher
  function initTabs(tabsId, prefix) {
    const container = document.getElementById(tabsId);
    if (!container) return;
    container.addEventListener('click', function(e) {
      const btn = e.target.closest('.tab-btn');
      if (!btn) return;
      container.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      const tabId = btn.dataset.tab;
      document.querySelectorAll('[id^="tab-"]').forEach(panel => {
        if (panel.id === 'tab-' + tabId) {
          panel.classList.add('active');
        } else if (container.querySelector('[data-tab="' + panel.id.replace('tab-','') + '"]')) {
          panel.classList.remove('active');
        }
      });
    });
  }

  // Better tab init: scope panels to each tab group
  function initTabGroup(tabsEl) {
    const buttons = tabsEl.querySelectorAll('.tab-btn');
    buttons.forEach(btn => {
      btn.addEventListener('click', function() {
        buttons.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const tabId = btn.dataset.tab;
        // Find sibling panels in same container
        const section = tabsEl.closest('.section, .container');
        if (section) {
          section.querySelectorAll('.tab-panel').forEach(panel => {
            panel.classList.toggle('active', panel.id === 'tab-' + tabId);
          });
        }
      });
    });
  }

  document.querySelectorAll('.tabs').forEach(initTabGroup);

