<script>
  // FAQ Accordion — one open at a time
  document.getElementById('faqList').addEventListener('click', function(e) {
    const btn = e.target.closest('.faq-question');
    if (!btn) return;
    const isOpen = btn.classList.contains('open');
    // Close all
    this.querySelectorAll('.faq-question').forEach(q => q.classList.remove('open'));
    this.querySelectorAll('.faq-answer').forEach(a => a.classList.remove('open'));
    // Open clicked if it was closed
    if (!isOpen) {
      btn.classList.add('open');
      btn.nextElementSibling.classList.add('open');
    }
  });

  // Tab switcher
  function initTabGroup(tabsEl) {
    const buttons = tabsEl.querySelectorAll('.tab-btn');
    buttons.forEach(btn => {
      btn.addEventListener('click', function() {
        buttons.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const tabId = btn.dataset.tab;
        const section = tabsEl.closest('.section, .container');
        if (section) {
          section.querySelectorAll('.tab-panel').forEach(panel => {
            panel.classList.toggle('active', panel.id === 'tab-' + tabId);
          });
        }
      });
    });
  }
  document.querySelectorAll('.tabs').forEach(initTabGroup);
</script>
