<script>
  function initTabGroup(tabsEl) {
    const buttons = tabsEl.querySelectorAll('.tab-btn');
    buttons.forEach(btn => {
      btn.addEventListener('click', function() {
        buttons.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        const tabId = btn.dataset.tab;
        const section = tabsEl.closest('.section, .container');
        if (section) {
          section.querySelectorAll('.tab-panel').forEach(panel => {
            panel.classList.toggle('active', panel.id === 'tab-' + tabId);
          });
        }
      });
    });
  }
  document.querySelectorAll('.tabs').forEach(initTabGroup);
</script>
